"""Round span edges to a fixed step for payroll."""

from typing import Iterable, List
from hourglass.parsing import format_span
from hourglass.models import Span

def _snap(minute: int, step: int) -> int:
    """Nearest multiple of step. Halfway rounds up."""
    return (minute + step // 2) // step * step

def _snap_span(span: Span, step: int) -> Span:
    start = _snap(span.start, step)
    return Span(start, _snap(span.end, step))

def _check_step(step: int) -> None:
    """A step must be positive and divide an hour evenly."""
    if step <= 0 or 60 % step:
        raise ValueError(f"step must divide 60: {step}")

def _label(span: Span) -> str:
    hours, minutes = divmod(span.minutes, 60)
    return f"{format_span(span)} ({hours}h {minutes}m)"

# ---
def label_rounded_spans(
    spans: Iterable[Span], step: int
) -> List[str]:
    """Round each span to the step and label it."""
    _check_step(step)
    snapped = [_snap_span(span, step) for span in spans]
    return [_label(span) for span in snapped]

