import unittest
from hourglass.rounding import label_rounded_spans
from hourglass.models import Span

class LabelRoundedSpansTests(unittest.TestCase):
    def test_rounds_to_nearest_step(self):
        labels = label_rounded_spans([Span(541, 1034)], 15)
        self.assertEqual(labels, ["09:00-17:15 (8h 15m)"])

    def test_halfway_rounds_up(self):
        labels = label_rounded_spans([Span(555, 1005)], 30)
        self.assertEqual(labels, ["09:30-17:00 (7h 30m)"])

    def test_labels_each_span_in_order(self):
        spans = [Span(540, 600), Span(720, 790)]
        labels = label_rounded_spans(spans, 5)
        self.assertEqual(labels[0], "09:00-10:00 (1h 0m)")
        self.assertEqual(labels[1], "12:00-13:10 (1h 10m)")

    def test_empty_list(self):
        self.assertEqual(label_rounded_spans([], 15), [])

    def test_rejects_steps_that_do_not_fit_an_hour(self):
        spans = [Span(540, 600)]
        for step in (0, -15, 7, 120):
            with self.subTest(step=step):
                with self.assertRaises(ValueError):
                    label_rounded_spans(spans, step)
